insert into public.lessons (id, subject_id, content_type, title, summary, content, sort_order) values
  ('english-description', 'english', 'lesson', 'Writing a description', 'Use specific words to help a reader imagine a place.', 'A clear description uses details gathered through the senses. Choose precise nouns and verbs, then add a few details about colour, sound, texture, or movement.', 1),
  ('english-edit', 'english', 'lesson', 'Reviewing your writing', 'Make a draft clearer with a careful review.', 'Read your work slowly. Check that each sentence is complete, ideas follow a sensible order, punctuation helps the reader, and spelling is checked for familiar words.', 3),
  ('english-story', 'english', 'lesson', 'Planning a short story', 'Give a story a beginning, a problem, and a resolution.', 'Before writing, decide who the story is about, where it happens, and what challenge the character faces. A simple plan helps events follow a clear order.', 2),
  ('maths-decimals', 'maths', 'lesson', 'Fractions as decimals', 'Connect tenths and hundredths to decimal notation.', 'A decimal point separates whole numbers from parts of a whole. One tenth is 0.1 and one hundredth is 0.01. You can use place value to compare decimal numbers.', 3),
  ('maths-equivalent', 'maths', 'lesson', 'Equivalent fractions', 'Different fractions can show the same amount.', 'Equivalent fractions have the same value. Multiply or divide both the numerator and denominator by the same number. For example, 1/2 and 2/4 describe the same amount.', 2),
  ('maths-fractions', 'maths', 'lesson', 'Understanding fractions', 'See how equal parts make a whole.', 'A fraction names equal parts of a whole. The top number counts the parts you have; the bottom number counts the equal parts in the whole. For example, 3/4 means three of four equal parts.', 1),
  ('science-care', 'science', 'lesson', 'Caring for our environment', 'Identify practical ways to protect habitats.', 'People can care for habitats by reducing litter, using resources responsibly, planting suitable native plants, and protecting places where living things feed and reproduce.', 3),
  ('science-food-chains', 'science', 'lesson', 'Food chains', 'Follow how energy moves between living things.', 'A food chain shows how energy passes from one organism to another. Green plants make their own food, herbivores eat plants, and predators may eat other animals.', 2),
  ('science-habitats', 'science', 'lesson', 'Habitats and living things', 'Explore how habitats support organisms.', 'A habitat is the place where an organism lives. It provides resources such as food, water, shelter, and space. Different organisms are suited to different habitats.', 1)
insert into public.assessments (id, title, subject_id, kind, duration_minutes, opens_at, published, created_by) values
  ('maths-practice', 'Mathematics practice', 'grade-6-mathematics', 'PRACTICE', 20, now() + interval '2 days', true, null),
  ('science-check', 'Science quick check', 'grade-6-science', 'QUIZ', 20, now() + interval '5 days', true, null)
insert into public.questions (id, assessment_id, prompt, options_json, correct_option, points, sort_order) values
  ('maths-practice-q1', 'maths-practice', 'What is 1/2 + 1/4?', '["1/6", "3/4", "2/6", "1"]'::jsonb, 1, 1, 1),
  ('maths-practice-q2', 'maths-practice', 'Which decimal is equal to 3/4?', '["0.25", "0.5", "0.75", "1.25"]'::jsonb, 2, 1, 2),
  ('science-check-q1', 'science-check', 'Which part of a plant absorbs water?', '["Flower", "Leaf", "Root", "Fruit"]'::jsonb, 2, 1, 1)
